import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

// Helper function to handle API errors
const handleApiError = (error, defaultReturn = []) => {
  console.error('API Error:', error.message);
  
  // If the server is down, provide a more specific message
  if (error.code === 'ERR_NETWORK') {
    console.warn('Backend server seems to be down. Make sure to run: npm run dev in the backend folder');
  }
  
  return defaultReturn;
};

// IMPROVED SERVER CONNECTION CHECK
export const checkServerConnection = async () => {
  try {
    console.log('🔍 Checking server connection...');
    const response = await axios.get(`${API_URL}/health`, {
      timeout: 5000, // 5 second timeout
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json'
      }
    });
    
    console.log('✅ Server response:', response.data);
    
    // Check if response is valid
    if (response.status === 200 && response.data && response.data.status === 'online') {
      console.log('✅ Server is online and responding correctly');
      return true;
    } else {
      console.warn('⚠️ Server responded but with unexpected format:', response.data);
      return false;
    }
  } catch (error) {
    console.error('❌ Server connection failed:', error.message);
    console.warn('Backend server not connected. Run: npm run dev in the backend folder');
    return false;
  }
};

// ALTERNATIVE CONNECTION CHECK - Try multiple endpoints
export const checkServerConnectionRobust = async () => {
  const endpoints = [
    `${API_URL}/health`,
    `${API_URL}/tasks`,
    `http://localhost:5000/` // Root endpoint
  ];
  
  for (const endpoint of endpoints) {
    try {
      console.log(`🔍 Trying endpoint: ${endpoint}`);
      const response = await axios.get(endpoint, { timeout: 3000 });
      if (response.status === 200) {
        console.log(`✅ Server is reachable at: ${endpoint}`);
        return true;
      }
    } catch (error) {
      console.log(`❌ Failed to reach: ${endpoint} - ${error.message}`);
    }
  }
  
  console.error('❌ All connection attempts failed');
  return false;
};

// TASKS API
export const fetchTasks = async () => {
  try {
    const response = await axios.get(`${API_URL}/tasks`);
    return response.data;
  } catch (error) {
    return handleApiError(error, []);
  }
};

export const addTask = async (task) => {
  try {
    const response = await axios.post(`${API_URL}/tasks`, task);
    return response.data;
  } catch (error) {
    return handleApiError(error, task);
  }
};

export const updateTask = async (id, task) => {
  try {
    const response = await axios.put(`${API_URL}/tasks/${id}`, task);
    return response.data;
  } catch (error) {
    return handleApiError(error, task);
  }
};

export const deleteTask = async (id) => {
  try {
    const response = await axios.delete(`${API_URL}/tasks/${id}`);
    return response.data;
  } catch (error) {
    return handleApiError(error, { message: "Task deleted successfully" });
  }
};

// NOTES API
export const fetchNotes = async () => {
  try {
    const response = await axios.get(`${API_URL}/notes`);
    return response.data;
  } catch (error) {
    return handleApiError(error, []);
  }
};

export const addNote = async (note) => {
  try {
    const response = await axios.post(`${API_URL}/notes`, note);
    return response.data;
  } catch (error) {
    return handleApiError(error, note);
  }
};

export const updateNote = async (id, note) => {
  try {
    const response = await axios.put(`${API_URL}/notes/${id}`, note);
    return response.data;
  } catch (error) {
    return handleApiError(error, note);
  }
};

export const deleteNote = async (id) => {
  try {
    const response = await axios.delete(`${API_URL}/notes/${id}`);
    return response.data;
  } catch (error) {
    return handleApiError(error, { message: "Note deleted successfully" });
  }
};

// MILESTONES API
export const fetchMilestones = async () => {
  try {
    const response = await axios.get(`${API_URL}/milestones`);
    return response.data;
  } catch (error) {
    return handleApiError(error, [
      { id: 1, name: 'Pre-Production', completed: false, active: true },
      { id: 2, name: 'Production', completed: false, active: false },
      { id: 3, name: 'Post-Production', completed: false, active: false }
    ]);
  }
};

export const updateMilestone = async (id) => {
  try {
    const response = await axios.put(`${API_URL}/milestones/${id}`, { active: true });
    return response.data;
  } catch (error) {
    return handleApiError(error, []);
  }
};

// IMAGES API
export const fetchImages = async () => {
  try {
    const response = await axios.get(`${API_URL}/images`);
    return response.data;
  } catch (error) {
    return handleApiError(error, []);
  }
};

export const uploadImage = async (file, metadata = {}) => {
  try {
    const formData = new FormData();
    formData.append('image', file);
    
    // Add metadata to form data
    Object.keys(metadata).forEach(key => {
      if (metadata[key] !== null && metadata[key] !== undefined) {
        formData.append(key, metadata[key]);
      }
    });
    
    const response = await axios.post(`${API_URL}/images`, formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      timeout: 30000 // 30 second timeout for uploads
    });
    return response.data;
  } catch (error) {
    console.error('Upload error:', error);
    throw error;
  }
};

export const updateImagePosition = async (id, position) => {
  try {
    const response = await axios.put(`${API_URL}/images/${id}/position`, position);
    return response.data;
  } catch (error) {
    return handleApiError(error, { message: "Position updated" });
  }
};

export const updateImageSize = async (id, size) => {
  try {
    const response = await axios.put(`${API_URL}/images/${id}/size`, size);
    return response.data;
  } catch (error) {
    return handleApiError(error, { message: "Size updated" });
  }
};

export const deleteImage = async (id) => {
  try {
    const response = await axios.delete(`${API_URL}/images/${id}`);
    return response.data;
  } catch (error) {
    return handleApiError(error, { message: "Image deleted successfully" });
  }
};

